import{_ as s}from"./chunks/22.DUDFIl6P.js";import{_ as l}from"./chunks/1._Wu06lVH.js";import{_ as t}from"./chunks/0.xVPDiwtD.js";import{_ as d}from"./chunks/10.CjdpXPJn.js";import{_ as c}from"./chunks/11.DiIhyeL-.js";import{_ as n}from"./chunks/0.B7TrDeTt.js";import{_ as g}from"./chunks/12.D1pIPcbk.js";import{_ as h}from"./chunks/4.ZpmvUIOM.js";import{_ as a}from"./chunks/0.DyB7G7H5.js";import{_ as p}from"./chunks/6.BMVImSlN.js";import{_ as m}from"./chunks/8.DS_jDXFp.js";import{_ as i}from"./chunks/0.C_OEUMPL.js";import{_ as u}from"./chunks/11.DPtnPYcq.js";import{_ as b}from"./chunks/100.DMbJtyMU.js";import{_ as f}from"./chunks/community.BdKwbEUF.js";import{_,C as y,o as w,c as v,ak as r,E as x}from"./chunks/framework.sbZkgmEx.js";const k="/projects/AiBlock/en/advanced-kit/assets/1.BoEEb2Wg.webp",P="/projects/AiBlock/en/advanced-kit/assets/2.1.spV0OpNX.webp",q="/projects/AiBlock/en/advanced-kit/assets/2.1.CyEbwCJo.webp",C="/projects/AiBlock/en/advanced-kit/assets/2.2.NWV5D54d.webp",A="/projects/AiBlock/en/advanced-kit/assets/3.zrrnuo33.webp",z="/projects/AiBlock/en/advanced-kit/assets/4.dAe4hBo6.webp",X=JSON.parse('{"title":"3.22 Air Defense Cannon","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.22 Air Defense Cannon.md","filePath":"docs/3.Creative Builds/3.22 Air Defense Cannon.md"}'),T={name:"docs/3.Creative Builds/3.22 Air Defense Cannon.md"};function j(B,e,S,D,O,E){const o=y("Pdf");return w(),v("div",null,[e[0]||(e[0]=r('<h1 id="_3-22-air-defense-cannon" tabindex="-1">3.22 Air Defense Cannon <a class="header-anchor" href="#_3-22-air-defense-cannon" aria-label="Permalink to &quot;3.22 Air Defense Cannon&quot;">​</a></h1><h2 id="_3-22-1-lesson-introduction" tabindex="-1">3.22.1 Lesson Introduction <a class="header-anchor" href="#_3-22-1-lesson-introduction" aria-label="Permalink to &quot;3.22.1 Lesson Introduction&quot;">​</a></h2><p>Centering on the intelligent air defense cannon model, this lesson explores coordinated programming across the servo, ultrasonic sensor, and RGB light module. It implements automated defense functions featuring reciprocating scanning and target detection followed by simulated firing. The content examines turret transmission principles, covers variable-driven stepping scan routines, and applies sensor-triggered lighting logic to illustrate how variables govern continuous mechanical motion.</p><img loading="lazy" height="1662" width="1662" src="'+s+'" class="common_img" style="width:400px;"><h2 id="_3-22-2-learning-objectives" tabindex="-1">3.22.2 Learning Objectives <a class="header-anchor" href="#_3-22-2-learning-objectives" aria-label="Permalink to &quot;3.22.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand the mechanical transmission principles of rotational turret aiming. Master programming methods using variables to govern incremental servo scanning. Comprehend target capture trigger logic combining ultrasonic sensing with RGB lighting effects.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical structure of the air defense cannon independently, mastering servo zero-point calibration and alignment procedures. Program basic reciprocating servo scanning routines. Implement complete system functionality uniting variable-controlled stepping scans, ultrasonic distance detection, and simulated RGB laser firing.</p></li><li><p><strong>Thinking Objectives</strong>: Establish programming concepts centered on incremental variable control for continuous motion, appreciating how dynamic variables replace static values to provide flexible control. Cultivate scan-detect-trigger target acquisition systems thinking. Strengthen understanding of integrated electromechanical design combining mechanical gearboxes with electronic feedback.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to radar tracking installations, security pan-tilt gimbals, and automated tracking cameras. Understand sensing and automated control technologies deployed in defense and security systems. Stimulate enthusiasm for defense technology, military engineering, and autonomous robotics.</p></li></ol><h2 id="_3-22-3-preparation" tabindex="-1">3.22.3 Preparation <a class="header-anchor" href="#_3-22-3-preparation" aria-label="Permalink to &quot;3.22.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>180° block servo</p></li><li><p>RGB light module</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-22-4-hands-on-project" tabindex="-1">3.22.4 Hands-On Project <a class="header-anchor" href="#_3-22-4-hands-on-project" aria-label="Permalink to &quot;3.22.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Air Defense Cannon, delivering a simulated defense system that autonomously scans airspace, acquires targets, and engages them with simulated fire. The system adopts a three-stage scan-detect-fire architecture: the servo drives the turret through reciprocating stepping scans between 0° and 180° in increments of 10°, while the ultrasonic sensor swivels synchronously to gauge distances across every angle. When detecting an obstacle at a distance of 20 cm or less, the servo halts scanning and the RGB light module illuminates red to simulate laser fire. Once the target clears the detection zone, the turret automatically resumes scanning. The overall workflow replicates standard search, track, and engagement protocols used in air defense systems.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),x(o,{src:"../../_static/shared/pdf/chapter_3/22.pdf"}),e[1]||(e[1]=r('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the RGB light module to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>B</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1566" width="2434" src="'+k+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+P+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+q+'" class="common_img" style="width:800px;"><ul><li>Select <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+C+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Serves as the main loop container, continuously executing internal code after power-on initialization</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="174" width="603" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+t+'"></td><td style="text-align:left;">Triggers internal code blocks when a short press is detected on the designated button</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="495" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+n+'"></td><td style="text-align:left;">Initializes the port connection for the ultrasonic sensor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="658" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+n+'"></td><td style="text-align:left;">Reads the obstacle distance measured by the ultrasonic sensor on the designated port, in centimeters (cm)</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+a+'"></td><td style="text-align:left;">Controls the 180° block servo on the designated port to rotate at a custom speed for a specified duration, continuing immediately to subsequent blocks without waiting if non-delay mode is selected</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="87" width="375" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+a+'"></td><td style="text-align:left;">Disables output to the 180° block servo on the designated port, halting rotation immediately</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="414" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+i+'"></td><td style="text-align:left;">Controls the RGB light module on the designated port to illuminate using a preset color</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="576" src="'+u+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+i+'"></td><td style="text-align:left;">Extinguishes the RGB light module on the designated port to cut off light output</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="494" width="430" src="'+A+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the ultrasonic sensor interface and sets the variables increment to 10 and angle to 90, positioning the turret in its default ready state. When an obstacle is detected within 20 cm, the system stops servo S1, bringing the turret to a stationary hold while engaging targets. When no obstacle is detected within 20 cm, servo S1 rotates between 0° and 180° at 30% speed, driving the cannon in a continuous back-and-forth scanning motion.</p></li></ul><img loading="lazy" height="1029" width="679" src="'+z+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+b+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1KQ-KBn3OmxCo6xKJkb7ZQZAuPW9brr5t?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-22-5-expansion-and-challenge" tabindex="-1">3.22.5 Expansion and Challenge <a class="header-anchor" href="#_3-22-5-expansion-and-challenge" aria-label="Permalink to &quot;3.22.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Precision Closed-Loop Tracking System</strong></p><p>Once a target is detected, continuously compute the angular deviation and adjust the servo orientation to maintain alignment. Incorporating a second servo enables pitch elevation control, establishing a two-axis tracking turret. This project illustrates the closed-loop feedback principle of detecting errors and correcting direction, extending discussions to radar tracking, missile guidance systems, and automated security gimbals.</p><p><strong>Project 2: Multi-Weapon Mode-Switching Turret</strong></p><p>Configure button inputs to toggle between three combat profiles: Machine Gun Mode featuring flashing red RGB bursts and barrel vibration, Laser Mode featuring solid red illumination and stabilized aiming, and Missile Mode featuring blue-white gradient fades with delayed launch sequences. Practice multi-state transitions and mode-specific programming to understand modular architecture, extending discussions to combat systems in video games and multi-role defense platforms.</p><h2 id="_3-22-6-q-a" tabindex="-1">3.22.6 Q&amp;A <a class="header-anchor" href="#_3-22-6-q-a" aria-label="Permalink to &quot;3.22.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why use a variable to regulate barrel elevation and azimuth rather than commanding fixed rotations directly between 0° and 180°?</strong></p><p>Answer: Utilizing variables for stepping scans ensures that <strong>the system samples each discrete angle along the scanning arc</strong>. If the servo simply sweeps between 0° and 180° without intermediate steps, the ultrasonic sensor cannot register distance measurements during transit and only samples at the extreme endpoints. This leaves intermediate sectors unmonitored, much like a surveillance radar checking only peripheral boundaries while ignoring the center. Incrementing by 10° per step allows the sensor to pause and measure distance at 0°, 10°, 20°, and onward up to 180°, ensuring comprehensive spatial coverage without blind spots. Furthermore, variable-based control offers high flexibility: accelerating the scan requires merely increasing the step value, refining angular resolution requires decreasing it, and restricting scans to a narrower sector requires adjusting boundary parameters. Replacing static constants with dynamic variables makes the codebase flexible and adaptable.</p><p><strong>Question 2: What principle governs toggling the increment variable to -10 upon reaching 180° and returning to 10 at 0°?</strong></p><p>Answer: This technique uses <strong>algebraic signs to control kinematic direction</strong>. The increment variable functions as both step magnitude and directional indicator: positive values increase the angle toward the right, while negative values decrease the angle toward the left. Starting from 90°, adding 10° during each iteration rotates the turret progressively rightward. Upon reaching 180°, the mechanism attains its mechanical limit. Inverting the increment value to -10 causes subsequent additions to reduce the angle by 10°, reversing turret travel leftward. Once the angle decreases to 0° at the opposite boundary, the increment returns to +10 to resume rightward motion. Toggling between positive and negative increments causes the angle to cycle smoothly between 0° and 180°, producing reciprocating scans. This reflects the standard boundary bounce pattern in game loops, commonly used for patrolling autonomous agents and bouncing projectiles.</p><h2 id="_3-22-7-technical-support-and-product-discussion" tabindex="-1">3.22.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-22-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.22.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+f+'" class="common_img" style="width:800px;"></a>',33))])}const Y=_(T,[["render",j]]);export{X as __pageData,Y as default};
